  console.log(`Conta da faculdade criada: ${config.ADMIN_EMAIL} / senha: ${config.ADMIN_SENHA} (troque depois!)`);
}

module.exports = db;
const crypto = require('node:crypto');

function hashSenha(senha) {
  const sal = crypto.randomBytes(16);
  const hash = crypto.scryptSync(senha, sal, 64);
  return `${sal.toString('hex')}:${hash.toString('hex')}`;
}

function confereSenha(senha, armazenado) {
  const [sal, hash] = String(armazenado).split(':');
  if (!sal || !hash) return false;
  const calculado = crypto.scryptSync(senha, Buffer.from(sal, 'hex'), 64);
  const esperado = Buffer.from(hash, 'hex');
  return esperado.length === calculado.length && crypto.timingSafeEqual(calculado, esperado);
}

module.exports = { hashSenha, confereSenha };
const app = require('./app');
const config = require('./config');

app.listen(config.PORTA, () => {
  console.log(`${config.NOME_APP} rodando em http://localhost:${config.PORTA}`);
});
// Mini sistema de templates: tudo que é interpolado é escapado automaticamente,
// a não ser que venha de outro html`` ou de raw(). Isso protege contra XSS.
class Raw {
  constructor(s) {
    this.s = s;
  }
  toString() {
    return this.s;
  }
}

const raw = (s) => new Raw(String(s));

function esc(v) {
  return String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function renderizar(v) {
  if (v === null || v === undefined || v === false) return '';
  if (v instanceof Raw) return v.s;
  if (Array.isArray(v)) return v.map(renderizar).join('');
  return esc(v);
}

function html(partes, ...valores) {
  let saida = partes[0];
  valores.forEach((v, i) => {
    saida += renderizar(v) + partes[i + 1];
  });
  return new Raw(saida);
}

module.exports = { html, raw, esc };
// Regras de pontuação e conquistas do Maxx.

